package main
import("encoding/json";"fmt";"go/scanner";"go/token";"os";"path/filepath";"reflect";"strings";"unicode")
type tok struct{ Kind token.Token; Lit string }
func scan(src string) []tok { var s scanner.Scanner; s.Init(token.NewFileSet().AddFile("source.go",-1,len(src)),[]byte(src),nil,0); var out []tok; for{_,t,l:=s.Scan();if t==token.EOF{break};out=append(out,tok{t,l})};return out }
func shape(ts []tok) []tok {out:=append([]tok(nil),ts...);for i:=range out{if out[i].Kind==token.STRING||out[i].Kind==token.CHAR{out[i].Lit="<literal>"}};return out}
func han(s string)bool{for _,r:=range s{if unicode.Is(unicode.Han,r){return true}};return false}
func main(){root:=os.Args[1];b,e:=os.ReadFile(filepath.Join(root,"agent-final-evidence/baseline.json"));if e!=nil{panic(e)};var base map[string]string;if e=json.Unmarshal(b,&base);e!=nil{panic(e)};files:=map[string]bool{};preserved:=map[string]bool{};var changes,unexpected []map[string]any;ok:=true
for p,old:=range base{if strings.HasSuffix(p,"_test.go"){continue};now,e:=os.ReadFile(filepath.Join(root,p));if e!=nil{panic(e)};a,z:=scan(old),scan(string(now));same:=reflect.DeepEqual(shape(a),shape(z));files[p]=same;ok=ok&&same;if !same{continue};allStrings:=true;for i,t:=range a{if t.Kind!=token.STRING&&t.Kind!=token.CHAR{continue};if t.Lit!=z[i].Lit{allStrings=false;c:=map[string]any{"path":p,"token_index":i,"before":t.Lit,"after":z[i].Lit};changes=append(changes,c);if !han(t.Lit)&&!(strings.HasSuffix(p,"terminalreason.go")&&(t.Lit=="\"：\""||t.Lit=="\"）\"")){unexpected=append(unexpected,c)}}};if strings.HasSuffix(p,"goals.go")||strings.HasSuffix(p,"planner.go")||strings.HasSuffix(p,"worker.go")||strings.HasSuffix(p,"mainagent.go")||strings.HasSuffix(p,"prompt.go")||strings.HasSuffix(p,"promptcatalog.go")||strings.HasSuffix(p,"wrapup.go")||strings.HasSuffix(p,"reporter_factories.go"){preserved[p]=allStrings;ok=ok&&allStrings}}
result:=map[string]any{"production_token_structure_unchanged":ok,"files":files,"role_prompt_files_all_literal_values_preserved":preserved,"literal_changes":changes,"unexpected_non_Han_literal_changes":unexpected,"method":"Go scanner ignores comments and masks string/character values for structure. All identifiers, numeric literals, operators and control flow equal baseline. Separately checks existing non-Han literals (machine keys, tool names, enums, SQL etc.) unchanged, apart from two translated terminal-summary punctuation literals. Natural-language equivalence still requires review."};b,_=json.MarshalIndent(result,"","  ");fmt.Println(string(b));if !ok||len(unexpected)>0{os.Exit(1)}}
